function buyerPost({
  title,
  slug,
  category = "web-development",
  description,
  excerpt,
  readingTime = "12-15 წუთი",
  keywords,
  sections,
  faqs,
  internalLinks = [],
  calculator = false,
}) {
  return {
    slug,
    type: "article",
    category,
    categoryTitle:
      blogCategories.find((item) => item.slug === category)?.title || "ბლოგი",
    featured: false,
    title,
    metaTitle: `${title} | Next-Hub Solutions`,
    description,
    excerpt,
    author: "Next-Hub Solutions",
    date: "2026-06-30",
    readingTime,
    tags: keywords,
    keywords,
    sections,
    faqs,
    serviceLinks: [...coreBuyerLinks],
    internalLinks,
    calculatorCta: calculator ? calculatorCta : undefined,
  };
}

