function buildHighIntentClusterPost(topic) {
  const [title, slug, category, group, focus, keywords] = topic;
  const categoryTitle =
    blogCategories.find((item) => item.slug === category)?.title || "ბლოგი";

  return {
    slug,
    type: "article",
    category,
    contentCluster: group,
    categoryTitle,
    featured: false,
    title,
    metaTitle: `${title} | Next-Hub Solutions`,
    description: `${title}: პრაქტიკული გზამკვლევი ქართული ბიზნესისთვის. გაიგეთ როგორ დაგეგმოთ პროექტი: ${focus}, რომ საიტმა იმუშაოს SEO-ზე, ნდობაზე და კონვერსიაზე.`,
    excerpt: `${title} ბიზნესისთვის: როგორ დაგეგმოთ სტრუქტურა, SEO, UX, ტექნიკური შესრულება და მხარდაჭერა ისე, რომ პროექტმა რეალური შედეგი მოიტანოს.`,
    author: "Next-Hub Solutions",
    date: "2026-07-10",
    readingTime: "9-12 წუთი",
    tags: [
      ...keywords,
      "Next-Hub Solutions",
      "ვებსაიტის დამზადება",
      "SEO მომსახურება",
      "Google Business Profile",
    ],
    keywords: [
      ...keywords,
      "Next-Hub Solutions",
      "ვებ დეველოპმენტი",
      "ვებ დიზაინი",
      "SEO ოპტიმიზაცია",
      "საიტის მოვლა",
    ],
    sections: clusterSections({ title, category, group, focus }),
    faqs: clusterFaqs({ title, group }),
    internalLinks: clusterTopicLinks(slug, group),
    serviceLinks,
  };
}

const highIntentClusterPosts = highIntentClusterTopics.map(
  buildHighIntentClusterPost
);

